q = 'What is the capital of France?'
a = 'Paris'
target = '731f21e4d0faff2b72d8e883eabe7cc41e2fa98e28a793b01183a19aa1e12600'

import hmac
for key in [b'', b'hashcards', b'card', b'basic']:
