        if h[:8] == target[:8]:
            print(f'BLAKE2b match: sep={repr(sep)}: {h[:8]}')
    except:
        pass

# Try BLAKE2s:
for sep in ['\n', '']:
    data = (q + sep + a).encode()
    try:
        h = hashlib.blake2s(data, digest_size=32).hexdigest()
        if h[:8] == target[:8]:
            print(f'BLAKE2s match: sep={repr(sep)}: {h[:8]}')
    except:
        pass

# Maybe it uses SHA256 but with a hash_id prefix (like Solana etc.):
# sha256(hash_id + data) where hash_id is a domain separator
