import hashlib, struct

# Let me try a systematic approach: what is the hash of 'A'+sep+'B' for ALL 1-byte separators?
# And check if any match '9a44dbd7':

found = False
for sep_byte in range(256):
    data = b'A' + bytes([sep_byte]) + b'B'
    h = hashlib.sha256(data).hexdigest()
    if h[:8] == '9a44dbd7':
        print(f'Found sep_byte={sep_byte} (0x{sep_byte:02x}): {h}')
        found = True

if not found:
    # Try 2-byte separators:
    for sep1 in range(256):
        for sep2 in range(256):
            data = b'A' + bytes([sep1, sep2]) + b'B'
            h = hashlib.sha256(data).hexdigest()
            if h[:8] == '9a44dbd7':
                print(f'Found 2-byte sep: {sep1:02x}{sep2:02x}: {h}')
                found = True
                break
        if found:
            break

# Also try with prefix/suffix:
for prefix in [b'', b'\x00', b'\x01']:
    for suffix in [b'', b'\x00', b'\x01']:
        data = prefix + b'A' + b'\n' + b'B' + suffix
        h = hashlib.sha256(data).hexdigest()
        if h[:8] == '9a44dbd7':
            print(f'Prefix+suffix: {prefix.hex()} | {suffix.hex()}: {h}')
